        { icon: "🎒", name: "10 backpacks + 7 radios", meta: "17 coords", desc: "Exact coordinates for every backpack, hip bag and radio station — bags also buy extra carry slots and drive two achievements.", href: "big-walk-backpacks.html", color: "blue" },
        { icon: "🎃", name: "The 8 easy-to-miss red gourds", meta: "True ending", desc: "The true ending needs 15 gourds and 8 of the red ones are the easiest to miss — sweep these leftover puzzles before you chase 100%.", href: "big-walk-additional-puzzles.html", color: "red" },
        { icon: "🏆", name: "All 12 achievements", meta: "100%", desc: "How to get every achievement — including the hidden ones that need a deliberate detour, so none of them slip past you.", href: "big-walk-achievements.html", color: "glow" }
